#!/bin/bash
# console_env.sh <if1|if2|fob>: prints the env the PS5 app (tools/ps5/ps5_app.c env_default lines, launcher defaults
# diag=0 fps=0 fg=0 ups=1 aa=1 aniso=16 look=0) sets for that game, as VAR=value words for if2_run.sh.
# Keep in sync with ps5_app.c (2026-11-10 audit: BC runs had been missing per-game console settings).
# t37 C (2026-11-12 console bisect on t35b): if2/FoB get PS3RECOMP_ENG_TEXHASH_SAFE=1 (manholes) + PS3RECOMP_VK_RMW_INPASS=1 (rails), per game.
g=$1
C="PS3_EVQ_KICK_MS=150 PS3_NO_GUEST_PTR_TRAP=1 PS3_EVQ_STALL=10 PS3_VERBOSE=0 PS3RECOMP_BE_ASYNC=1 PS3_GCM_LEGACY_LEAN=1
PS3RECOMP_ENG_RMW_DIRECT=2 PS3_GCM_FAST_WORDS=1 PS3RECOMP_ENG_MICRO=1 PS3RECOMP_ENG_DRAW_FAST=1 PS3RECOMP_ENG_TEXHASH_ASYNC=1
PS3_ENG_DIRTY=1 PS3_BA_DEDUP=1 PS3_BA_VBUF_ASYNC=1 PS3_BA_IDX_REF=1 PS3_SPU_CALL_FAST=1 PS3RECOMP_ENG_FPSLOG=1 PS3_FRAMEGEN=0 PS3_UPSCALER=1 PS3_AA=1 PS3_ANISO=16 PS3_LOOK=0 PS3_FSR_SHARP=0
PS3_SKIP_MOVIES=intro PS3_LANG=en GCM_SEMA_ACQUIRE=1 GCM_SEMA_ACQUIRE_MS=200 GCM_PARK_GRACE_MS=1000 PS3_BUTTON_ICONS=playstation"
case $g in
 if1) G="PS3RECOMP_ENG_TEXHASH_SAFE=1 PS3RECOMP_VK_RMW_INPASS=1 PS3_VK_STENCIL=1 PS3_VK_STENCIL_TEXMASK=07 PS3_MK_SPIN_US=25 PS3_IF1_AUDIO_PATCH=0 GCM_FLIP_IMMEDIATE=2 PS3_VK_GAMMA=0.85 PS3_AUDIO_OUT_CH=2 PS3_IF1_SPURS2_SPUS=2 PS3_IF1_SPURS1_SPUS=6 PS3_SPU_GROUP_CAP=8 PS3RECOMP_ENG_SHADOW_BIAS=0.001
      PS3RECOMP_ENG_CULL_FLIP_ZETA=0F340000 PS3RECOMP_ENG_SHADOW_CULL=0F340000:2:4 PS3RECOMP_ENG_CASTER_FAST=3 PS3_BA_VS_DELTA=1 PS3_ENG_DT_TEXDELTA=1 PS3_BA_REPLAY_OP=1 PS3_SPU_OVL_PREFIX=1 PS3_IF1_JL_SPIN_US=50 PS3_BA_KICK=512 PS3_BA_NOLOCK=1 PS3_AUDIO_PRIO=640
      PS3_IF1_JL_WAIT_US=30 PS3_AUDIO_QUEUE=36 PS3_AUDIO_PACE=8 PS3_AUDIO_HOLD_MIN=1 PS3_VK_SIGNED_MODE=bias
      PS3RECOMP_ENG_GPU_LIGHT= PS3RECOMP_ENG_GPU_SSAO= PS3RECOMP_ENG_GPU_SSAO_WB=1" ;;
 if2) G="PS3RECOMP_ENG_TEXHASH_SAFE=1 PS3RECOMP_VK_RMW_INPASS=1 PS3_BA_VS_DELTA=1 PS3_ENG_DT_TEXDELTA=1 PS3_BA_REPLAY_OP=1 PS3RECOMP_ENG_DT_FETCHSKIP=1 PS3RECOMP_ENG_DRAW_FAST_N=8 PS3RECOMP_ENG_OVERLAY_BIAS=-8 PS3RECOMP_ENG_OVERLAY_BIAS_MINRT=2 PS3RECOMP_ENG_OVERLAY_BIAS_CLASS0=2 PS3_GCM_REPORT_MEM=0 PS3_BA_KICK=512 PS3_BA_NOLOCK=1 PS3_GCM_FAST_WORDS=2 PS3_VK_STENCIL=1 GCM_FLIP_IMMEDIATE=2 PS3_AUDIO_QUEUE=36 PS3_AUDIO_HOLD_MIN=1 PS3RECOMP_ENG_GPU_LIGHT=07000B80:07384B80 PS3RECOMP_ENG_GPU_SSAO=0F800000 PS3RECOMP_ENG_GPU_SSAO_WB=0" ;;
 fob) G="PS3RECOMP_ENG_TEXHASH_SAFE=1 PS3RECOMP_VK_RMW_INPASS=1 PS3_BA_VS_DELTA=1 PS3_ENG_DT_TEXDELTA=1 PS3_BA_REPLAY_OP=1 PS3RECOMP_ENG_DT_FETCHSKIP=1 PS3RECOMP_ENG_DRAW_FAST_N=8 PS3RECOMP_ENG_OVERLAY_BIAS=-8 PS3RECOMP_ENG_OVERLAY_BIAS_MINRT=2 PS3RECOMP_ENG_OVERLAY_BIAS_CLASS0=2 PS3_GCM_REPORT_MEM=0 PS3_BA_KICK=512 PS3_BA_NOLOCK=1 PS3_GCM_FAST_WORDS=2 PS3_VK_STENCIL=1 GCM_FLIP_IMMEDIATE=2 PS3_AUDIO_QUEUE=36 PS3_AUDIO_HOLD_MIN=1 PS3RECOMP_ENG_GPU_LIGHT=0703D780:073C1780 PS3RECOMP_ENG_GPU_SSAO=0F800000 PS3RECOMP_ENG_GPU_SSAO_WB=1" ;;
 *) echo "usage: $0 if1|if2|fob" >&2; exit 1 ;;
esac
echo $C $G
